from qiskit import QuantumCircuit
from qiskit.circuit.library import HGate, CPhaseGate, SwapGate

qc = QuantumCircuit(5)

# Apply Hadamard gates to all qubits
for qubit in range(5):
    qc.append(HGate(), [qubit])

# Apply CPhase gates between qubits with the correct angle
for j in range(1, 5):
    for k in range(j):
        qc.append(CPhaseGate(2 * 3.141592653589793 / (2 ** (j - k + 1))), [k, j])

# Add the final SWAP-reversal layer
for i in range(2):
    qc.append(SwapGate(), [i, 4 - i])

